// Invite-code generation and hashing. Codes and secrets are never logged and
// never appear in error messages.

import { createHmac, randomBytes } from "node:crypto";

const CROCKFORD = "REDACTED";
const MIN_SECRET_LENGTH = 32;
const GROUP_SIZE = 4;

// 20 random bytes = 160 bits = exactly 32 base32 characters, in 8 groups of 4.
export function generateInviteCode(): string {
  const bytes = randomBytes(20);
  let bits = 0;
  let value = 0;
  let out = "";
  for (const byte of bytes) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      out += CROCKFORD[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
    value &= (1 << bits) - 1;
  }
  const groups: string[] = [];
  for (let i = 0; i < out.length; i += GROUP_SIZE) {
    groups.push(out.slice(i, i + GROUP_SIZE));
  }
  return groups.join("-");
}

export function normalizeCode(code: string): string {
  return code.trim().toUpperCase().replace(/[-\s]/g, "");
}

function requireSecret(secret: string): void {
  if (typeof secret !== "string" || secret.length < MIN_SECRET_LENGTH) {
    throw new Error(
      `HMAC secret must be at least ${MIN_SECRET_LENGTH} characters`,
    );
  }
}

export function hashCode(code: string, secret: string): string {
  requireSecret(secret);
  return createHmac("sha256", secret).update(normalizeCode(code)).digest("hex");
}

export function hashIp(ip: string, secret: string): string {
  requireSecret(secret);
  return createHmac("sha256", secret).update(`ip:v1:${ip.trim()}`).digest("hex");
}
// Storage contract for live mode. Callers must fail closed: any
// LiveStoreUnavailable means "do not run".

export class LiveStoreUnavailable extends Error {
  constructor() {
    // Deliberately generic: driver errors can echo connection details.
    super("live store unavailable");
    this.name = "LiveStoreUnavailable";
  }
}

export type CodeMode = "synthetic" | "live";

export type ReserveFailure =
  | "invalid_code"
  | "disabled"
  | "no_runs_left"
  | "run_in_progress";

export type ReserveResult =
  | { ok: true; runId: string; runsRemaining: number; mode: CodeMode }
  | { ok: false; reason: ReserveFailure };

export interface RunOutcome {
  status: "completed" | "failed" | "budget_exhausted";
  searched: number;
  enriched: number;
  providerCostUsd: number;
  modelCostUsd: number;
  errorCategory?: string;
}

export interface HitResult {
  allowed: boolean;
  retryAfterSeconds: number;
}

// Never carries a hash.
export interface CodeSummary {
  label: string;
  maxRuns: number;
  runsUsed: number;
  disabled: boolean;
  mode: CodeMode;
}

export interface LiveAdmin {
  // false when the label (or hash) already exists.
  createCode(
    label: string,
    maxRuns: number,
    codeHash: string,
    mode?: CodeMode,
  ): Promise<boolean>;
  listCodes(): Promise<CodeSummary[]>;
  // The three below return false when no code has that label.
  disableCode(label: string): Promise<boolean>;
  enableCode(label: string): Promise<boolean>;
  addRuns(label: string, n: number): Promise<boolean>;
  setMode(label: string, mode: CodeMode): Promise<boolean>;
}

export interface LiveStore {
  isLiveEnabled(): Promise<boolean>;
  setLiveEnabled(value: boolean): Promise<void>;
  reserveRun(
    codeHash: string,
    now: Date,
    lockSeconds: number,
  ): Promise<ReserveResult>;
  finishRun(runId: string, outcome: RunOutcome): Promise<void>;
  // For a run that failed before any paid call: gives the run back.
  releaseRun(runId: string): Promise<void>;
  // Fixed-window counter.
  hit(
    bucket: string,
    now: Date,
    windowSeconds: number,
    limit: number,
  ): Promise<HitResult>;
  admin: LiveAdmin;
}
