// Builds the real model client: an OpenAI SDK client pointed at the LiteLLM
// gateway, instrumented with neatlogs' wrapOpenAI, inside the agent's retry
// and cost-accounting adapter.
//
// Everything is passed in explicitly: this module never reads process.env,
// never initialises or closes tracing (entry points call initTracing() /
// closeTracing() from src/core/observability/tracing.ts), and never puts the
// API key in an error message.

import { wrapOpenAI } from "neatlogs/openai";
import OpenAI from "openai";
import { LITELLM_GATEWAY_BASE_URL, LLM_REQUEST_TIMEOUT_MS } from "./llm-policy";
import {
  type LlmRetryPolicy,
  OpenAiCompatibleLlmClient,
  ResponseHeaderRecorder,
} from "./openai-llm";

type Fetch = (input: string | URL | Request, init?: RequestInit) => Promise<Response>;

export interface GatewayClientOptions {
  // Supplied by the entry point. Never logged.
  readonly apiKey: string;
  // Defaults to the shared LiteLLM gateway.
  readonly baseURL?: string;
  // Per HTTP attempt. Defaults to LLM_REQUEST_TIMEOUT_MS (30 s).
  readonly timeoutMs?: number;
  // Transport override, for tests. Defaults to the global fetch.
  readonly fetch?: Fetch;
}

export interface GatewayLlmClientOptions extends GatewayClientOptions {
  readonly policy?: Partial<Omit<LlmRetryPolicy, "request_timeout_ms">>;
  readonly sleep?: (ms: number) => Promise<void>;
  readonly now?: () => number;
  readonly wall_clock?: () => number;
}

export interface GatewayClient {
  // The wrapOpenAI-instrumented SDK client.
  readonly client: OpenAI;
  // Response headers recorded by the client's fetch.
  readonly headers: ResponseHeaderRecorder;
}

export function createGatewayOpenAIClient(options: GatewayClientOptions): GatewayClient {
  if (typeof options.apiKey !== "string" || options.apiKey.trim() === "") {
    throw new Error("The model gateway API key is missing.");
  }
  const headers = new ResponseHeaderRecorder();
  const baseFetch: Fetch = options.fetch ?? ((input, init) => globalThis.fetch(input, init));
  const recordingFetch: Fetch = async (input, init) => {
    const response = await baseFetch(input, init);
    headers.record(response.headers);
    return response;
  };
  const sdk = new OpenAI({
    apiKey: options.apiKey,
    baseURL: options.baseURL ?? LITELLM_GATEWAY_BASE_URL,
    timeout: options.timeoutMs ?? LLM_REQUEST_TIMEOUT_MS,
    // Our adapter owns retries; the SDK default (2) would add hidden requests.
    maxRetries: 0,
    fetch: recordingFetch,
    // Explicit, so the SDK does not fall back to OPENAI_* environment values.
    organization: null,
    project: null,
    webhookSecret: null,
    logLevel: "warn",
  });
  return { client: wrapOpenAI(sdk), headers };
}

export function createGatewayLlmClient(options: GatewayLlmClientOptions): OpenAiCompatibleLlmClient {
  const { client, headers } = createGatewayOpenAIClient(options);
  return new OpenAiCompatibleLlmClient({
    client,
    headers,
    records_llm_spans: true,
    policy: {
      ...options.policy,
      request_timeout_ms: options.timeoutMs ?? LLM_REQUEST_TIMEOUT_MS,
    },
    secrets: [options.apiKey],
    sleep: options.sleep,
    now: options.now,
    wall_clock: options.wall_clock,
  });
}
// Provider interface: the only way the agent reaches company data. Real and
// fixture providers both implement it. Plain TypeScript only.

import type { RawCompany, RunConfig } from "../types";

// Why a provider call failed.
export type ProviderErrorCategory =
  | "auth_failed"
  | "rate_limited"
  | "timeout"
  | "bad_request"
  | "no_match"
  | "budget_cap_reached"
  | "empty_or_partial";

export interface ProviderError {
  readonly category: ProviderErrorCategory;
  readonly message: string;
}

// Outcome of one provider call. Providers return errors; they do not throw.
export type ProviderResult<T> =
  | {
      readonly ok: true;
      readonly data: T;
      // US dollars this call cost.
      readonly cost_usd: number;
      // Number of upstream API calls made.
      readonly calls: number;
    }
  | { readonly ok: false; readonly error: ProviderError };

// Filters for a company search.
export interface SearchFilters {
  readonly country: string;
  readonly industries: readonly string[];
  readonly employee_count_ranges: readonly string[];
}

export interface CompanyProvider {
  autocompleteIndustry(query: string): Promise<ProviderResult<readonly string[]>>;
  searchCompanies(
    filters: SearchFilters,
    limit: number,
  ): Promise<ProviderResult<readonly RawCompany[]>>;
  enrichCompanies(
    linkedin_urls: readonly string[],
  ): Promise<ProviderResult<readonly RawCompany[]>>;
}

// What a BudgetGuard has used so far.
export interface BudgetSnapshot {
  readonly cost_usd: number;
  readonly searched: number;
  readonly enriched: number;
}

// Tracks spend against the run's caps. Providers must check it before every
// paid call and return budget_cap_reached instead of calling when it says no.
export class BudgetGuard {
  private readonly max_search_results: number;
  private readonly max_enrichments: number;
  private cost_usd = 0;
  private searched = 0;
  private enriched = 0;

  constructor(config: Pick<RunConfig, "max_search_results" | "max_enrichments">) {
    this.max_search_results = config.max_search_results;
    this.max_enrichments = config.max_enrichments;
  }

  // True if searching `limit` more companies stays within the cap.
  canSearch(limit: number): boolean {
    return limit >= 0 && this.searched + limit <= this.max_search_results;
  }

  // True if enriching `count` more companies stays within the cap.
  canEnrich(count: number): boolean {
    return count >= 0 && this.enriched + count <= this.max_enrichments;
  }

  recordSearch(n: number, cost: number): void {
    this.searched += n;
    this.cost_usd += cost;
  }

  recordEnrich(n: number, cost: number): void {
    this.enriched += n;
    this.cost_usd += cost;
  }

  snapshot(): BudgetSnapshot {
    return {
      cost_usd: this.cost_usd,
      searched: this.searched,
      enriched: this.enriched,
    };
  }
}
// The results page's synthetic run: the real improved pipeline over the
// synthetic fixtures, with FixtureProvider and the deterministic FakeLlmClient
// only. No environment variables, no external calls, no tracing. The requested
// mode is checked first, before any dependency is constructed.

import { FakeLlmClient } from "../../../core/agent/fake-llm";
import { runImprovedPipeline } from "../../../core/agent/improved-pipeline";
import type { LlmClient } from "../../../core/agent/llm";
import type { PipelineResult } from "../../../core/agent/types";
import { FixtureProvider } from "../../../core/data/fixture-provider";
import type { BudgetSnapshot, CompanyProvider } from "../../../core/data/provider";
import { guardrailDemoResponder } from "./guardrail-demo";
import { parseRequestedMode } from "./mode";
import { type ResultsDto, toResultsDto } from "./presentation";
import {
  SIMULATED_COST_PER_RECORD,
  SYNTHETIC_FACT_PROVIDER,
  SYNTHETIC_ICP,
  SYNTHETIC_RUN_CONFIG,
  SYNTHETIC_TRACE_LABEL,
} from "./synthetic-config";

// Builders for the run's dependencies. Separate so tests can confirm a
// rejected mode never reaches them.
export interface SyntheticDependencies {
  createProvider(): { provider: CompanyProvider; budget: { snapshot(): BudgetSnapshot } };
  createLlm(): LlmClient;
}

export const syntheticDependencies: SyntheticDependencies = {
  createProvider() {
    const provider = new FixtureProvider({
      config: SYNTHETIC_RUN_CONFIG,
      cost_per_record: SIMULATED_COST_PER_RECORD,
    });
    return { provider, budget: provider.budget };
  },
  createLlm() {
    return new FakeLlmClient({ respond: guardrailDemoResponder });
  },
};

export type SyntheticRun =
  | { readonly kind: "rejected"; readonly reason: string }
  | { readonly kind: "ok"; readonly result: PipelineResult };

export async function runSyntheticPipeline(
  requestedMode: unknown,
  dependencies: SyntheticDependencies = syntheticDependencies,
): Promise<SyntheticRun> {
  const mode = parseRequestedMode(requestedMode);
  if (!mode.ok) return { kind: "rejected", reason: mode.reason };

  const { provider, budget } = dependencies.createProvider();
  const llm = dependencies.createLlm();
  const result = await runImprovedPipeline(
    SYNTHETIC_ICP,
    { provider, budget, llm, fact_provider: SYNTHETIC_FACT_PROVIDER, trace_id: SYNTHETIC_TRACE_LABEL },
    { config: SYNTHETIC_RUN_CONFIG },
  );
  return { kind: "ok", result };
}

export type SyntheticResults =
  | { readonly kind: "rejected"; readonly reason: string }
  | { readonly kind: "ok"; readonly results: ResultsDto };

// What the page renders: the presentation DTO, never the pipeline result.
export async function loadSyntheticResults(
  requestedMode: unknown,
  dependencies: SyntheticDependencies = syntheticDependencies,
): Promise<SyntheticResults> {
  const run = await runSyntheticPipeline(requestedMode, dependencies);
  return run.kind === "rejected" ? run : { kind: "ok", results: toResultsDto(run.result) };
}
// Fixed inputs for the results page's synthetic run. They mirror the
// evaluation set-up used by scripts/run-pipeline.ts (10 searched companies,
// 5 enrichments, an ICP with no filters), which the web app cannot import.

import type { IcpInput } from "../../../core/agent/types";
import { DEFAULT_RUN_CONFIG, type RunConfig } from "../../../core/types";

export const SYNTHETIC_RUN_CONFIG: RunConfig = {
  ...DEFAULT_RUN_CONFIG,
  max_search_results: 10,
  max_enrichments: 5,
};

// No filters: every synthetic fixture company is searched.
export const SYNTHETIC_ICP: IcpInput = {
  industry: "",
  employee_count_ranges: [],
  locations: [],
  keywords: [],
  excluded_domains: [],
};

// The data comes from FixtureProvider, so facts are labelled "fixture".
export const SYNTHETIC_FACT_PROVIDER = "fixture" as const;

// A fixed label instead of a random trace id: this run is never traced.
export const SYNTHETIC_TRACE_LABEL = "synthetic-results-demo";

// Simulated per-record prices for FixtureProvider, matching the runner's
// SIMULATED_COST_PER_RECORD. Nothing is charged: no provider is called.
export const SIMULATED_COST_PER_RECORD = { search: 0.069, enrich: 0.6 } as const;
// Server-only entry points for the results page. The official evidence
// summary is imported as a JSON module, so it is bundled with the server code
// at build time: no filesystem read at request time, and the file itself is
// never sent to the browser. Only the validated summary is rendered.

import "server-only";
import evidenceSummary from "../../../../evidence/summary.json";
import { type EvidenceState, parseEvidenceSummary } from "./evidence";
import { loadSyntheticResults, type SyntheticResults } from "./synthetic-run";

export function loadResults(requestedMode: unknown): Promise<SyntheticResults> {
  return loadSyntheticResults(requestedMode);
}

export function loadEvidence(): EvidenceState {
  return parseEvidenceSummary(evidenceSummary as unknown);
}
// The only run mode the results page supports. This web app has no live
// execution path: anything other than the synthetic mode is rejected on the
// server before any provider, model client or pipeline is constructed.

export const SYNTHETIC_MODE = "synthetic";

export type ModeCheck =
  | { readonly ok: true; readonly mode: typeof SYNTHETIC_MODE }
  | { readonly ok: false; readonly reason: string };

export const UNSUPPORTED_MODE_REASON =
  "Only synthetic mode is available on this page. Live Crustdata and real-model runs are not supported by the web app.";

// Accepts the raw `mode` search parameter: absent means synthetic. A repeated
// parameter arrives as an array and is rejected, as is an empty string or any
// other value ("live", "crustdata", ...).
export function parseRequestedMode(value: unknown): ModeCheck {
  if (value === undefined || value === SYNTHETIC_MODE) {
    return { ok: true, mode: SYNTHETIC_MODE };
  }
  return { ok: false, reason: UNSUPPORTED_MODE_REASON };
}
// In-memory LiveStore used by the contract suite (no database).

import type {
  CodeMode,
  CodeSummary,
  HitResult,
  LiveStore,
  ReserveResult,
  RunOutcome,
} from "../../src/server/live/store";

interface Code {
  id: string;
  hash: string;
  label: string;
  maxRuns: number;
  runsUsed: number;
  disabled: boolean;
  mode: CodeMode;
  lockedUntil: number | null;
}
interface Run {
  codeId: string;
  status: string;
  outcome?: RunOutcome;
}

export class FakeLiveStore implements LiveStore {
  private enabled = false;
  private codes: Code[] = [];
  readonly runs = new Map<string, Run>();
  private hits = new Map<string, number>();
  private seq = 0;

  async isLiveEnabled() {
    return this.enabled;
  }
  async setLiveEnabled(value: boolean) {
    this.enabled = value;
  }

  async reserveRun(
    codeHash: string,
    now: Date,
    lockSeconds: number,
  ): Promise<ReserveResult> {
    const c = this.codes.find((x) => x.hash === codeHash);
    if (!c) return { ok: false, reason: "invalid_code" };
    if (c.disabled) return { ok: false, reason: "disabled" };
    if (c.runsUsed >= c.maxRuns) return { ok: false, reason: "no_runs_left" };
    if (c.lockedUntil !== null && c.lockedUntil > now.getTime()) {
      return { ok: false, reason: "run_in_progress" };
    }
    c.runsUsed += 1;
    c.lockedUntil = now.getTime() + lockSeconds * 1000;
    const runId = `run-${++this.seq}`;
    this.runs.set(runId, { codeId: c.id, status: "started" });
    return { ok: true, runId, runsRemaining: c.maxRuns - c.runsUsed, mode: c.mode };
  }

  async finishRun(runId: string, outcome: RunOutcome) {
    const r = this.runs.get(runId);
    if (!r || r.status !== "started") return;
    r.status = outcome.status;
    r.outcome = outcome;
    this.codes.find((c) => c.id === r.codeId)!.lockedUntil = null;
  }

  async releaseRun(runId: string) {
    const r = this.runs.get(runId);
    if (!r || r.status !== "started") return;
    r.status = "released";
    const c = this.codes.find((x) => x.id === r.codeId)!;
    c.runsUsed = Math.max(c.runsUsed - 1, 0);
    c.lockedUntil = null;
  }

  async hit(
    bucket: string,
    now: Date,
    windowSeconds: number,
    limit: number,
  ): Promise<HitResult> {
    const w = windowSeconds * 1000;
    const start = Math.floor(now.getTime() / w) * w;
    const key = `${bucket}@${start}`;
    const count = (this.hits.get(key) ?? 0) + 1;
    this.hits.set(key, count);
    if (count <= limit) return { allowed: true, retryAfterSeconds: 0 };
    return {
      allowed: false,
      retryAfterSeconds: Math.max(Math.ceil((start + w - now.getTime()) / 1000), 1),
    };
  }

  private byLabel(label: string) {
    return this.codes.find((c) => c.label === label);
  }

  readonly admin = {
    createCode: async (
      label: string,
      maxRuns: number,
      codeHash: string,
      mode: CodeMode = "synthetic",
    ) => {
      if (this.codes.some((c) => c.label === label || c.hash === codeHash)) {
        return false;
      }
      this.codes.push({
        id: `code-${this.codes.length + 1}`,
        hash: codeHash,
        label,
        maxRuns,
        runsUsed: 0,
        disabled: false,
        mode,
        lockedUntil: null,
      });
      return true;
    },
    listCodes: async (): Promise<CodeSummary[]> =>
      this.codes.map((c) => ({
        label: c.label,
        maxRuns: c.maxRuns,
        runsUsed: c.runsUsed,
        disabled: c.disabled,
        mode: c.mode,
      })),
    disableCode: async (label: string) => {
      const c = this.byLabel(label);
      if (c) c.disabled = true;
      return !!c;
    },
    enableCode: async (label: string) => {
      const c = this.byLabel(label);
      if (c) c.disabled = false;
      return !!c;
    },
    setMode: async (label: string, mode: CodeMode) => {
      const c = this.byLabel(label);
      if (c) c.mode = mode;
      return !!c;
    },
    addRuns: async (label: string, n: number) => {
      const c = this.byLabel(label);
      if (c) c.maxRuns += n;
      return !!c;
    },
  };
}

