      assessment: p.assessment.status,
      llm_call_number: p.llm_call?.call_number ?? null,
    })),
  };
}

function buildProvider(args: Args, config: RunConfig): CompanyProvider & { readonly budget: BudgetGuard } {
  if (args.provider === "fixture") {
