      `  unavailable=${llmCost.calls_by_basis.unavailable} calls`,
  );
  console.log(
    `prompt   version=${PROMPT_VERSION} safety_rules_sha256=${sha256Hex(PROMPT_SAFETY_RULES).slice(0, 12)} system_hashes=${system_prompt_hashes.join(",") || "none"}`,
  );
  const fmt = (c: { valid: number; flagged: number; rejected: number }) =>
    `valid=${c.valid} flagged=${c.flagged} rejected=${c.rejected}`;
  console.log("post-hoc validation (counts)");
  console.log(`  searched  ${fmt(validation.searched)}`);
  console.log(`  enriched  ${fmt(validation.enriched)}  wasted_enrichments=${validation.wasted_enrichments}`);
  console.log(`  delivered ${fmt(validation.delivered)}  duplicate_groups=${validation.delivered_duplicate_groups}`);
  const tally = (r: Readonly<Record<string, number>>) =>
    Object.entries(r)
      .map(([key, n]) => `${key}=${n}`)
      .join(",") || "none";
  console.log("final-record validation (counts)");
  console.log(`  all       ${fmt(finalVal.all)}`);
  console.log(`  assessed  ${fmt(finalVal.assessed)}`);
  console.log(`  issues    ${tally(finalVal.issues_by_code_field)}`);
  console.log(
    `  changed_by_enrichment=${finalVal.changed_by_enrichment.count} (${tally(finalVal.changed_by_enrichment.transitions)})` +
      ` ids=${finalVal.changed_by_enrichment.company_ids.join(",") || "none"}`,
  );
  const m = computeBaselineCitationMetrics(result, args.provider);
  if (args.pipeline === "baseline") {
    console.log(
      `citations assessed=${m.assessed} drafts=${m.outreach_drafts} cited=${m.cited_fact_ids} citeable=${m.citeable} missing=${m.missing}` +
        ` cross_company=${m.cross_company} model_provider=${m.model_provider} uncertain=${m.uncertain}` +
        ` other_non_citeable=${m.other_non_citeable} drafts_with_violations=${m.drafts_with_violations.count}`,
    );
  } else if (result.metrics) {
    const im = result.metrics;
    console.log(
      `improved rejected=${im.rejected.count} flagged=${im.flagged.count} duplicates_removed=${im.duplicates_removed.count}` +
        ` eligible=${im.enrichment.eligible.count} requested=${im.enrichment.requested.count} enriched=${im.enrichment.enriched.count}` +
        ` assessments_failed=${im.assessments_failed.count} outreach_suppressed=${im.outreach_suppressed.count}` +
        ` claim_violations=${im.claim_violations.count} (drafts=${im.claim_violations.drafts})`,
    );
    const g = summarizeGuardFindings(result.prospects, im);
    const byCode = (r: Readonly<Record<string, number>>) =>
      Object.entries(r)
        .map(([code, n]) => `${code}=${n}`)
        .join(",") || "none";
    console.log(`guards   findings: ${byCode(g.findings_by_code)}  claim_violations: ${byCode(g.claim_violations_by_code)}`);
  } else {
    console.log("improved metrics unavailable (the run stopped before validation)");
  }
  console.log(formatOutreachLine(summarizeOutreachKept(result.prospects), m));
  console.log(`issues   ${result.issues.map((i) => i.code).join(", ") || "none"}`);
  console.log(`report   ${path}`);
  if (result.status === "stopped") {
    console.error("The run stopped early; see the issue codes above.");
  }
  process.exitCode = exitCodeForStatus(result.status);
}

main().catch((err) => {
  console.error(
    err instanceof UsageError ? err.message : `Run failed: ${err instanceof Error ? err.message : "unknown error"}`,
  );
  process.exitCode = exitCodeForError(err);
});

// Agent-local types for the baseline and improved pipelines. These are not
// part of the shared contract in src/core/types.ts. Both pipelines return
// the same PipelineResult; fields only the improved pipeline fills are
// optional, so the baseline result is unchanged.

import type {
  BudgetSnapshot,
  CompanyProvider,
  ProviderErrorCategory,
  SearchFilters,
} from "../data/provider";
import type {
  AnyFact,
  Assessment,
  RawCompany,
  Run,
  RunConfig,
  RunStep,
  Validation,
} from "../types";
import type { LlmCallMeta, LlmClient, LlmErrorCategory } from "./llm";
import type { LlmCostBasis, LlmKeySpend } from "./llm-cost";
import type { PipelineTracer } from "./tracer";

// What the user asked for. Built by the app from its form.
export interface IcpInput {
  // Free text; mapped to provider industry labels via autocomplete.
  readonly industry: string;
  // Provider range strings, e.g. "51-200". Empty means any size.
  readonly employee_count_ranges: readonly string[];
  // Countries. SearchFilters takes one, so only the first is searched.
  readonly locations: readonly string[];
  // Given to the model only; the provider has no keyword filter.
  readonly keywords: readonly string[];
  // Given to the model only; neither pipeline filters on them.
  readonly excluded_domains: readonly string[];
}

// Which pipeline produced a result.
export type PipelineKind = "naive_baseline" | "improved";

export type EnrichmentStatus =
  | "enriched" // returned by the enrich call
  | "not_returned" // requested, but missing from the response
  | "skipped_budget" // not requested, or refused, because of the enrichment cap
  | "skipped_no_linkedin" // no LinkedIn URL, so it cannot be enriched
  | "skipped_ineligible" // improved only: rejected by validation (incl. duplicates)
  | "failed"; // the enrich call failed

export interface EnrichmentOutcome {
  readonly status: EnrichmentStatus;
  // Set when the enrich call returned an error.
  readonly error_category?: ProviderErrorCategory;
}

export type CheckSeverity = "error" | "warning";

export type CheckFindingCode =
  // validateAssessment
  | "fit_score_out_of_range"
  | "criterion_score_out_of_range"
  | "missing_criterion"
  | "unexpected_criterion"
  | "duplicate_criterion"
  | "unknown_fact_reference"
  | "uncertain_fact_reference"
  // checkClaims
  | "no_citations"
  | "duplicate_citation"
  | "unknown_citation"
  | "model_fact_citation"
  | "non_citeable_citation"
  | "unsupported_number";

// One problem found by validateAssessment() or checkClaims(). Errors make the
// assessment (or outreach) unusable; warnings are recorded only.
export interface CheckFinding {
  readonly code: CheckFindingCode;
  readonly severity: CheckSeverity;
  readonly message: string;
  readonly fact_id?: string;
  readonly criterion?: string;
}

export interface CheckResult {
  // True when there are no error findings.
  readonly ok: boolean;
  readonly findings: readonly CheckFinding[];
}

// What the improved pipeline's guardrails decided for one company.
export interface AssessmentChecks {
  readonly assessment: CheckResult;
  // Absent when the assessment failed validation or drafted no outreach.
  readonly claims?: CheckResult;
  // kept: outreach passed checkClaims. removed: it failed and was dropped
  // from the assessment. none: there was no usable outreach to check.
  readonly outreach: "kept" | "removed" | "none";
}

export type AssessmentOutcome =
  | { readonly status: "assessed"; readonly assessment: Assessment }
  | {
      readonly status: "failed";
      // invalid_assessment: improved only; validateAssessment() found errors.
      readonly reason: "llm_error" | "malformed_output" | "truncated" | "invalid_assessment";
      readonly message: string;
      // Set when reason is "llm_error".
      readonly error_category?: LlmErrorCategory;
    }
  | {
      readonly status: "not_assessed";
      // llm_stopped: an earlier call failed in a way every later call would
      // repeat (auth failure, or rate limiting after all retries).
      // rejected / duplicate: improved only; validation rejected the record
      // (duplicate when the reason was a duplicate_domain issue).
      readonly reason:
        | "llm_call_cap"
        | "not_enriched"
        | "llm_stopped"
        | "rejected"
        | "duplicate";
    };

// The model call made for one company. The same object feeds the result and
// the assess_company span, so the two always agree.
export interface LlmCallRecord extends LlmCallMeta {
  // 1-based position among this run's logical model calls.
  readonly call_number: number;
}

// One company in a pipeline result. The baseline fills only the first four
// fields; the improved pipeline also records validation, facts and checks.
// Deliberately not the shared Prospect, whose validation and facts are
// required: the baseline has neither, and faking them would hide that.
export interface BaselineProspect {
  // The enriched record when enrichment returned it, else the search record.
  readonly raw: RawCompany;
  readonly enrichment: EnrichmentOutcome;
  readonly assessment: AssessmentOutcome;
  // Absent when no model call was made for this company.
  readonly llm_call?: LlmCallRecord;
  // Improved only: the verdict on the search record.
  readonly search_validation?: Validation;
  // Improved only: the verdict on `raw` (re-run after enrichment).
  readonly validation?: Validation;
  // Improved only: buildFacts(raw, validation); empty when rejected.
  readonly facts?: readonly AnyFact[];
  // Improved only: present when a model assessment was checked.
  readonly checks?: AssessmentChecks;
}

// Same type, named for code that handles either pipeline.
export type PipelineProspect = BaselineProspect;

// Model cost for the run, split by how each figure is known.
export interface LlmCostSummary {
  readonly gateway_reported_usd: number;
  readonly estimated_usd: number;
  // gateway_reported_usd + estimated_usd.
  readonly known_usd: number;
  readonly calls_by_basis: Readonly<Record<LlmCostBasis, number>>;
  // False when any call's cost is unavailable; known_usd is then a lower
  // bound, not the run's cost.
  readonly complete: boolean;
  // From the most recent response that carried LiteLLM key-spend headers.
  readonly latest_key_spend?: LlmKeySpend;
}

export type PipelineIssueCode =
  | "industry_not_recognised"
  | "industry_autocomplete_failed"
  | "extra_locations_ignored"
  | "search_budget_exhausted"
  | "search_no_match"
  | "search_failed"
  | "enrich_budget_exhausted"
  | "enrich_no_results"
  | "enrich_partial"
  | "enrich_failed"
  | "llm_call_cap_reached"
  | "llm_stopped"
  | "llm_cost_incomplete";

// A run-level note or failure. Per-company problems live on the prospect.
export interface PipelineIssue {
  readonly step: RunStep;
  readonly code: PipelineIssueCode;
  readonly message: string;
  // Provider failures.
  readonly error_category?: ProviderErrorCategory;
  // Model failures.
  readonly llm_error_category?: LlmErrorCategory;
}

// completed_empty: the search found nothing. stopped: search failed, so the
// run could not continue.
export type PipelineStatus = "completed" | "completed_empty" | "stopped";

// A count with the company ids behind it. Ids only, never records.
export interface IdCount {
  readonly count: number;
  readonly company_ids: readonly number[];
}

// Guardrail outcomes of an improved run, as counts and company ids only.
// Plain JSON: no records, no Maps or Sets.
export interface ImprovedRunMetrics {
  // Rejected by validation for a reason other than being a duplicate.
  readonly rejected: IdCount;
  // Usable but suspicious (status "flagged" in the final validation).
  readonly flagged: IdCount;
  // Later duplicates removed (duplicate_domain), at search or after enrichment.
  readonly duplicates_removed: IdCount;
  readonly enrichment: {
    // Not rejected at search and has a LinkedIn URL. Ids in search order.
    readonly eligible: IdCount;
    // Sent to the enrich call, within the cap. Ids in the order sent:
    // "valid" companies first, then "flagged", each in search order.
    readonly requested: IdCount;
    // Returned by the enrich call. Ids in search order.
    readonly enriched: IdCount;
  };
  readonly assessments_failed: IdCount & {
    readonly by_reason: Readonly<Record<string, number>>;
  };
  // Outreach drafted by the model but removed because it failed checkClaims.
  readonly outreach_suppressed: IdCount;
  readonly claim_violations: {
    // Error findings from checkClaims across all drafts.
    readonly count: number;
    // Drafts with at least one violation.
    readonly drafts: number;
    readonly by_code: Readonly<Record<string, number>>;
    readonly company_ids: readonly number[];
  };
}

// Citation quality of a baseline run's outreach, measured after the fact
// with the improved pipeline's validation and facts. Counts and ids only.
export interface BaselineCitationMetrics {
  readonly fact_provider: FactProvenance;
  readonly prospects: number;
  readonly assessed: number;
  readonly outreach_drafts: number;
  // Distinct fact ids cited across all drafts (counted once per draft).
  readonly cited_fact_ids: number;
  // Each cited id falls into exactly one of these, in this order of checks:
  // missing (no such fact for that company), model_provider, uncertain,
  // other_non_citeable (any other status outside CITEABLE_FACT_STATUSES),
  // citeable.
  readonly citeable: number;
  readonly missing: number;
  // The part of `missing` that names another company's fact.
  readonly cross_company: number;
  readonly model_provider: number;
  readonly uncertain: number;
  readonly other_non_citeable: number;
  // Drafts citing at least one id that is not citeable.
  readonly drafts_with_violations: IdCount;
}

export interface PipelineResult {
  readonly pipeline: PipelineKind;
  readonly status: PipelineStatus;
  readonly run: Run;
  readonly filters: SearchFilters;
  readonly prospects: readonly BaselineProspect[];
  readonly issues: readonly PipelineIssue[];
  readonly usage: {
    readonly provider: BudgetSnapshot;
    readonly max_search_results: number;
    readonly max_enrichments: number;
    // Logical model calls; this is what max_llm_calls_per_run caps.
    readonly llm_calls: number;
    readonly max_llm_calls_per_run: number;
    // Attempts behind those calls, retries included, as reported by the
    // LLM client (real HTTP requests for the gateway client).
    readonly llm_http_attempts: number;
    readonly llm_cost: LlmCostSummary;
  };
  // Improved only: guardrail outcomes as counts and ids. Absent for the
  // baseline and for improved runs that stopped before validation.
  readonly metrics?: ImprovedRunMetrics;
}

// Where company data came from, for buildFacts() provenance: "fixture" for
// FixtureProvider data, "crustdata" for real Crustdata data.
export type FactProvenance = "crustdata" | "fixture";

// Dependencies for runBaselinePipeline (and the base for the improved
// pipeline's). fact_provider is optional here so existing baseline callers
// need not set it; the baseline never reads it.
export interface PipelineDeps {
  readonly provider: CompanyProvider;
  // The BudgetGuard the provider enforces, read to size enrich requests.
  // CompanyProvider does not expose one, so it is passed separately (for a
  // FixtureProvider, pass provider.budget).
  readonly budget: { snapshot(): BudgetSnapshot };
  readonly llm: LlmClient;
  // Ignored by the baseline. Allowed so one deps object can drive both
  // pipelines.
  readonly fact_provider?: FactProvenance;
  readonly tracer?: PipelineTracer;
  // Defaults to a random UUID.
  readonly trace_id?: string;
  // Milliseconds clock for step timings. Defaults to Date.now.
  readonly now?: () => number;
}

// Dependencies for runImprovedPipeline: the same, but fact provenance must be
// stated explicitly. The pipeline never guesses or defaults it.
export interface ImprovedPipelineDeps extends PipelineDeps {
  readonly fact_provider: FactProvenance;
}

export interface PipelineOptions {
  // Defaults to DEV_RUN_CONFIG.
  readonly config?: RunConfig;
  // Baseline only: which companies go to the model. Defaults to every
  // searched company. The improved pipeline always assesses only enriched,
  // non-rejected companies and ignores this option.
  readonly assess?: "all_searched" | "enriched_only";
}
// Model-call policy constants for the agent. Reviewed values live here, not
// scattered through the adapter. None of these are spending limits: the
// per-run model spend cap and the shared-key spend threshold are not yet
// agreed and belong in the shared RunConfig.

// Shared LiteLLM gateway (OpenAI-compatible). Callers may override it.
export const LITELLM_GATEWAY_BASE_URL = "https://litellm.vision.aivar.app/v1";

// Every model request is deterministic-as-possible.
export const LLM_TEMPERATURE = 0;

// Per HTTP attempt. The OpenAI SDK default is 10 minutes.
export const LLM_REQUEST_TIMEOUT_MS = 30_000;

// Retries after the first attempt, for rate-limit responses only. The SDK's
// own retries are disabled (maxRetries: 0) so these are the only ones.
export const LLM_MAX_RETRIES = 2;

// Wait before retry n (1-based) when the gateway sends no usable Retry-After.
export const LLM_RETRY_BACKOFF_MS: readonly number[] = [1_000, 2_000];

// Longest single wait we will honour. A longer Retry-After ends the call as
// rate_limited instead of retrying early.
export const LLM_MAX_RETRY_WAIT_MS = 10_000;

// Wall-clock budget for one logical model call, including retries and waits.
// Each attempt's timeout is clipped to what is left of it.
export const LLM_CALL_DEADLINE_MS = 60_000;

// Rough fallback rates documented by Abhijit, used only when the gateway
// does not report a cost. Results are labelled "estimated", never measured.
export const ESTIMATED_INPUT_USD_PER_MILLION_TOKENS = 1.1;
export const ESTIMATED_OUTPUT_USD_PER_MILLION_TOKENS = 5.5;
// Presentation DTO for the results page. Built field by field from the
// improved pipeline's result: no raw company record, source-record detail,
// prompt, model output metadata, trace data or credential reaches it, and
// nothing is spread from pipeline objects. Plain JSON throughout.

import { isCiteableFact } from "../../../core/agent/assessment-checks";
import type {
  AssessmentOutcome,
  BaselineProspect,
  CheckFinding,
  EnrichmentStatus,
  IdCount,
  ImprovedRunMetrics,
  PipelineResult,
  PipelineStatus,
} from "../../../core/agent/types";
import type { FactProvider, FactStatus, ValidationStatus } from "../../../core/types";
import { SYNTHETIC_MODE } from "./mode";

export interface IdCountDto {
  readonly count: number;
  readonly company_ids: readonly number[];
}

export interface FindingDto {
  readonly code: string;
  readonly severity: "error" | "warning";
  readonly message: string;
  readonly fact_id?: string;
  readonly criterion?: string;
}

export interface FactDto {
  readonly id: string;
  readonly claim: string;
  readonly status: FactStatus;
  readonly provider: FactProvider;
  readonly citeable: boolean;
}

export type AssessmentDto =
  | {
      readonly status: "assessed";
      readonly fit_score: number;
      readonly criterion_scores: readonly {
        readonly criterion: string;
        readonly score: number;
        readonly fact_ids: readonly string[];
      }[];
      readonly uncertainty_notes: readonly string[];
    }
  | { readonly status: "failed"; readonly reason: string; readonly message: string }
  | { readonly status: "not_assessed"; readonly reason: string };

export type OutreachDto =
  | { readonly state: "kept"; readonly body: string; readonly cited_fact_ids: readonly string[] }
  // The pipeline removed the draft; only the findings that caused it remain.
  | { readonly state: "suppressed"; readonly findings: readonly FindingDto[] }
  | { readonly state: "none" };

export interface ProspectDto {
  readonly company_id: number;
  readonly display_name: string;
  readonly search_validation_status: ValidationStatus | null;
  readonly validation: {
    readonly status: ValidationStatus | null;
    readonly issues: readonly {
      readonly code: string;
      readonly field: string;
      readonly reason: string;
      readonly related_company_id?: number;
    }[];
  };
  readonly enrichment_status: EnrichmentStatus;
  readonly assessment: AssessmentDto;
  readonly facts: readonly FactDto[];
  readonly outreach: OutreachDto;
  readonly guard: {
    readonly assessment_findings: readonly FindingDto[];
    readonly claim_findings: readonly FindingDto[];
  };
}

export interface MetricsDto {
  readonly rejected: IdCountDto;
  readonly flagged: IdCountDto;
  readonly duplicates_removed: IdCountDto;
  readonly enrichment_eligible: IdCountDto;
  readonly enrichment_requested: IdCountDto;
  readonly enrichment_enriched: IdCountDto;
  readonly assessments_failed: IdCountDto;
  readonly assessments_failed_by_reason: readonly { readonly reason: string; readonly count: number }[];
  readonly outreach_suppressed: IdCountDto;
  readonly claim_violations: number;
  readonly claim_violation_drafts: number;
  readonly claim_violations_by_code: readonly { readonly code: string; readonly count: number }[];
}

export interface ResultsDto {
  readonly mode: typeof SYNTHETIC_MODE;
  readonly run: {
    readonly status: PipelineStatus;
    readonly fact_provider: "fixture";
    readonly limits: {
      readonly max_search_results: number;
      readonly max_enrichments: number;
      readonly max_llm_calls_per_run: number;
    };
    readonly counts: {
      readonly searched: number;
      readonly enriched: number;
      readonly delivered: number;
      readonly assessed: number;
      readonly model_calls: number;
    };
    // Nothing external is called in synthetic mode.
    readonly actual_spend_usd: 0;
    // FixtureProvider's simulated per-record prices; never a real charge.
    readonly simulated_provider_cost_usd: {
      readonly search: number;
      readonly enrich: number;
      readonly total: number;
    };
  };
  readonly metrics: MetricsDto | null;
  readonly issues: readonly { readonly code: string; readonly message: string }[];
  readonly prospects: readonly ProspectDto[];
}

const MAX_NAME_LENGTH = 80;

function idCount(value: IdCount): IdCountDto {
  return { count: value.count, company_ids: [...value.company_ids] };
}

function entries<K extends string>(record: Readonly<Record<string, number>>, key: K) {
  return Object.keys(record)
    .sort()
    .map((name) => ({ [key]: name, count: record[name] }) as { [P in K]: string } & { count: number });
}

function finding(f: CheckFinding): FindingDto {
  return {
    code: f.code,
    severity: f.severity,
    message: f.message,
    ...(f.fact_id !== undefined ? { fact_id: f.fact_id } : {}),
    ...(f.criterion !== undefined ? { criterion: f.criterion } : {}),
  };
}

function displayName(name: string, companyId: number): string {
  const clean = name.replace(/\s+/g, " ").trim();
  if (clean === "") return `Company ${companyId}`;
  return clean.length > MAX_NAME_LENGTH ? `${clean.slice(0, MAX_NAME_LENGTH - 1)}…` : clean;
}

function assessmentDto(outcome: AssessmentOutcome): AssessmentDto {
  switch (outcome.status) {
    case "assessed":
      return {
        status: "assessed",
        fit_score: outcome.assessment.fit_score,
        criterion_scores: outcome.assessment.criterion_scores.map((s) => ({
          criterion: s.criterion,
          score: s.score,
          fact_ids: [...s.fact_ids],
        })),
        uncertainty_notes: [...outcome.assessment.uncertainty_notes],
      };
    case "failed":
      return { status: "failed", reason: outcome.reason, message: outcome.message };
    case "not_assessed":
      return { status: "not_assessed", reason: outcome.reason };
  }
}

function outreachDto(p: BaselineProspect): OutreachDto {
  if (p.checks?.outreach === "removed") {
    return {
      state: "suppressed",
      findings: (p.checks.claims?.findings ?? []).filter((f) => f.severity === "error").map(finding),
    };
  }
  if (p.assessment.status === "assessed" && p.assessment.assessment.outreach) {
    const { body, cited_fact_ids } = p.assessment.assessment.outreach;
    return { state: "kept", body, cited_fact_ids: [...cited_fact_ids] };
  }
  return { state: "none" };
}

export function toProspectDto(p: BaselineProspect): ProspectDto {
  const companyId = p.raw.crustdata_company_id;
  const validation = p.validation ?? p.search_validation;
  return {
    company_id: companyId,
    display_name: displayName(p.raw.name, companyId),
    search_validation_status: p.search_validation?.status ?? null,
    validation: {
      status: validation?.status ?? null,
      issues: (validation?.issues ?? []).map((issue) => ({
        code: issue.code,
        field: issue.field,
        reason: issue.reason,
        ...(issue.related_company_id !== undefined ? { related_company_id: issue.related_company_id } : {}),
      })),
    },
    enrichment_status: p.enrichment.status,
    assessment: assessmentDto(p.assessment),
    facts: (p.facts ?? []).map((f) => ({
      id: f.id,
      claim: f.claim,
      status: f.status,
      provider: f.source.provider,
      citeable: isCiteableFact(f),
    })),
    outreach: outreachDto(p),
    guard: {
      assessment_findings: (p.checks?.assessment.findings ?? []).map(finding),
      claim_findings: (p.checks?.claims?.findings ?? []).map(finding),
    },
  };
}

function metricsDto(m: ImprovedRunMetrics): MetricsDto {
  return {
    rejected: idCount(m.rejected),
    flagged: idCount(m.flagged),
    duplicates_removed: idCount(m.duplicates_removed),
    enrichment_eligible: idCount(m.enrichment.eligible),
    enrichment_requested: idCount(m.enrichment.requested),
    enrichment_enriched: idCount(m.enrichment.enriched),
    assessments_failed: idCount(m.assessments_failed),
    assessments_failed_by_reason: entries(m.assessments_failed.by_reason, "reason"),
    outreach_suppressed: idCount(m.outreach_suppressed),
    claim_violations: m.claim_violations.count,
    claim_violation_drafts: m.claim_violations.drafts,
    claim_violations_by_code: entries(m.claim_violations.by_code, "code"),
  };
}

export function toResultsDto(result: PipelineResult): ResultsDto {
  const costs = result.run.cost_usd_by_step;
  return {
    mode: SYNTHETIC_MODE,
    run: {
      status: result.status,
      fact_provider: "fixture",
      limits: {
        max_search_results: result.usage.max_search_results,
        max_enrichments: result.usage.max_enrichments,
