      try {
        await client.query("BEGIN");
        const out = await fn({ query: (t, p) => client.query(t, p) });
        await client.query("COMMIT");
        return out;
      } catch (err) {
        await client.query("ROLLBACK").catch(() => undefined);
        throw err;
      } finally {
        client.release();
      }
    },
  };
  return { store: new PgLiveStore(db), close: () => pool.end() };
